#include "../../AfxHookSource2/Filmmaker/Movie/SceneKeyframeCatalog.h"
#include <iostream>
#include <stdexcept>
using namespace Filmmaker;
using namespace Filmmaker::SceneKeys;
void Check(bool pass,const char* label) {if(!pass)throw std::runtime_error(label);}
int main(int argc,char** argv) {try {
    const auto& catalog=Catalog();
    if(argc>1&&std::string(argv[1])=="--catalog") {
        JsonBuilder j;j.BeginArray();
        for(const auto&s:catalog){j.BeginObject();j.StringField("id",s.id);j.StringField("label",s.label);j.StringField("family",s.family);j.StringField("group",s.group);j.StringField("groupId",s.groupId);j.StringField("type",TypeName(s.type));j.IntField("components",s.components);j.DoubleField("min",s.min);j.DoubleField("max",s.max);j.Key("initial");WriteValue(j,s.initial,s.type==ChannelType::SkyId);j.EndObject();}
        j.EndArray();std::cout<<"// Generated by SceneKeyframeTrackTests --catalog; native catalog is authoritative.\nwindow.MvmSceneCatalog = "<<j.Str()<<";\n";return 0;
    }
    Check(catalog.size()>70,"complete safe property catalog");
    Check(!FindSpec(catalog,"env.stormSeed")&&!FindSpec(catalog,"env.worldGi"),"unsafe properties excluded");
    const auto& exposure=*FindSpec(catalog,"exposure");const auto& color=*FindSpec(catalog,"skyColor");
    const auto& angle=*FindSpec(catalog,"lightDirection.yaw");const auto& toggle=*FindSpec(catalog,"cloudsVisible");
    const auto& asset=*FindSpec(catalog,"sky");
    for(const auto&s:catalog)Check(ValidValue(s,s.initial),"valid catalog default");
    // Names are what the key changes (CONFIG's own labels), never the id: a missing entry in the
    // catalog's name table falls back to the id, and "Sun Position yaw" / "Smoke Tint · T" were
    // what id-derived names looked like.
    std::set<std::string> seen;
    for(const auto&s:catalog){
        Check(!s.label.empty()&&s.label!=s.id&&s.label.find('.')==std::string::npos&&s.label.find("\xC2\xB7")==std::string::npos,("named from CONFIG, not the id: "+s.id).c_str());
        Check(seen.insert(s.family+"|"+s.label).second,("unique name within its tab: "+s.label).c_str());
    }
    auto name=[&](const char* id){const auto* s=FindSpec(catalog,id);return s?s->label:std::string();};
    auto group=[&](const char* id){const auto* s=FindSpec(catalog,id);return s?s->group:std::string();};
    Check(name("env.sunAzimuth")=="Sun azimuth"&&name("env.sunElevation")=="Sun elevation","procedural sun named as CONFIG's SKY page");
    Check(name("sunPosition.yaw")=="Custom sun azimuth"&&name("sunPosition.pitch")=="Custom sun elevation","absolute sun position says azimuth/elevation");
    Check(name("lightDirection.yaw")=="Sun rotate"&&name("lightDirection.pitch")=="Sun tilt","map sun named as CONFIG's Sun page");
    Check(group("env.sunAzimuth")=="Sky"&&group("env.fogDensity")=="Fog"&&group("env.snow")=="Ground"&&group("env.bloom")=="Looks","environment groups follow CONFIG's ENVIRONMENT cards");
    SceneKeyframeTrack track;
    track.BeginEdit();track.data.armed.insert(exposure.id);int first=track.Put(exposure,100,{{1},{}});track.EndEdit();
    bool active=true;Check(Sample(exposure,track.data.fields[exposure.id],100,{{3},{}},&active).numbers[0]==3&&!active,"single key follows baseline");
    track.BeginEdit();int second=track.Put(exposure,200,{{2},{}});track.EndEdit();
    Check(Sample(exposure,track.data.fields[exposure.id],150.5,{{3},{}}).numbers[0]>1.5,"fractional capture sampling");
    Check(Sample(exposure,track.data.fields[exposure.id],201,{{3},{}}).numbers[0]==3,"outside follows baseline");
    Check(track.Put(exposure,100,{{1.2},{}})==first,"same tick preserves id");
    track.BeginEdit();track.selected={first};track.MoveSelected(catalog,100,0);track.EndEdit();Check(track.Find(exposure.id,first)->tick==100,"collision refuses move");
    track.BeginEdit();track.MoveSelected(catalog,10,.2);track.EndEdit();Check(track.Find(exposure.id,first)->tick==110,"move key");
    Check(track.Undo()&&track.Find(exposure.id,first)->tick==100,"undo grouped move");Check(track.Redo()&&track.Find(exposure.id,first)->tick==110,"redo move");
    // A drag sends the TOTAL offset since the press. A step refused at a collision is not lost:
    // the next one is measured from the same origin and lands where the pointer is.
    track.BeginEdit();track.selected={first};
    track.MoveSelected(catalog,40,0);Check(track.Find(exposure.id,first)->tick==150,"drag offset from press");
    track.MoveSelected(catalog,90,0);Check(track.Find(exposure.id,first)->tick==150,"collision keeps the last valid position");
    track.MoveSelected(catalog,95,0);Check(track.Find(exposure.id,first)->tick==205,"past the collision the key is back under the pointer");
    track.MoveSelected(catalog,95,50);Check(track.Find(exposure.id,first)->value.numbers[0]==exposure.max,"value clamps at the bound");
    track.MoveSelected(catalog,95,-0.5);Check(std::fabs(track.Find(exposure.id,first)->value.numbers[0]-0.9)<1e-9,"a clamped value comes back without drift");
    Check(track.EndEdit()&&track.Undo()&&track.Find(exposure.id,first)->tick==110,"one drag is one undo step");
    track.BeginEdit();track.Put(color,100,{{255,0,0,0},{}});track.Put(color,200,{{0,0,255,255},{}});track.Put(toggle,100,{{0},{}});track.Put(toggle,200,{{1},{}});track.Put(asset,100,{{},""});track.Put(asset,200,{{},"night"});track.EndEdit();
    auto c=Sample(color,track.data.fields[color.id],150,color.initial);Check(c.numbers[1]<100&&c.numbers[3]>127&&c.numbers[3]<128,"OKLab and alpha");
    Check(Sample(toggle,track.data.fields[toggle.id],199,toggle.initial).numbers[0]==0,"step holds left");Check(Sample(toggle,track.data.fields[toggle.id],200,toggle.initial).numbers[0]==1,"step exact endpoint");
    Check(Sample(asset,track.data.fields[asset.id],150,asset.initial).asset.empty(),"asset holds left");
    track.Put(angle,100,{{350},{}});track.Put(angle,200,{{10},{}});auto a=Sample(angle,track.data.fields[angle.id],150,angle.initial);Check(std::fabs(std::remainder(a.numbers[0],360))<1e-6,"angle shortest wrap");
    track.data.fields[exposure.id][0].right={true,.3,.4};
    const auto encoded=Encode(track.data);TrackData restored;std::string error;
    Check(Decode(encoded,catalog,restored,error)&&Encode(restored)==encoded,"round trip ids handles colors assets arming");
    {   // Smooth is AE's Auto Bezier: solved from the neighbours, kept through the file, and the
        // slope of an angle follows the turn its segment really takes.
        const double lo=exposure.min,span=exposure.max-exposure.min;
        std::vector<Key> ks(3);
        for(int i=0;i<3;++i){ks[i].id=900+i;ks[i].tick=100.0*i;ks[i].value={{lo+span*(i==0?.1:i==1?.3:.7)},{}};ks[i].left.autoTan=ks[i].right.autoTan=true;}
        Check(RefreshAutoTangents(exposure,ks)&&!RefreshAutoTangents(exposure,ks),"auto handles solve once and then hold");
        Check(std::fabs(ks[1].right.dv-(span*.6/200.0)*100.0/3.0)<1e-9&&ks[1].right.active&&ks[1].left.active,"Catmull-Rom slope at 1/3 influence");
        Check(!ks[0].left.active&&ks[0].left.autoTan&&ks[0].right.active,"an end key has no outer handle but stays auto");
        ks[1].right={true,.5,.01};ks[2].value.numbers[0]=lo+span*.9;RefreshAutoTangents(exposure,ks);
        Check(!ks[1].right.autoTan&&std::fabs(ks[1].right.dv-.01)<1e-12&&ks[1].left.autoTan,"a hand-edited side is a plain Bezier the refresh leaves alone");
        TrackData autoData;autoData.armed.insert(exposure.id);autoData.fields[exposure.id]=ks;autoData.nextId=903;TrackData autoBack;std::string autoError;
        Check(Decode(Encode(autoData),catalog,autoBack,autoError)&&autoBack.fields[exposure.id][1].left.autoTan&&!autoBack.fields[exposure.id][1].right.autoTan,"handle kinds round trip");
        std::vector<Key> turn(3);
        const double deg[]={350,10,30};
        for(int i=0;i<3;++i){turn[i].id=950+i;turn[i].tick=100.0*i;turn[i].value={{deg[i]},{}};turn[i].left.autoTan=turn[i].right.autoTan=true;}
        RefreshAutoTangents(angle,turn);
        Check(std::fabs(turn[1].right.dv-(40.0/200.0)*100.0/3.0)<1e-9,"an angle slopes the short way round");
    }
    auto bad=encoded;auto pos=bad.find("\"version\":1");bad.replace(pos,11,"\"version\":2");Check(!Decode(bad,catalog,restored,error)&&Encode(restored)==encoded,"invalid version transactional");
    bad=encoded;pos=bad.find("\"value\":\"night\"");bad.replace(pos,15,"\"value\":false");Check(!Decode(bad,catalog,restored,error),"asset type rejected");
    auto corrupt=track.data;corrupt.fields[exposure.id].push_back(corrupt.fields[exposure.id][0]);Check(!Decode(Encode(corrupt),catalog,restored,error),"duplicate IDs rejected");
    track.BeginEdit();track.data.muted.insert(color.id);Check(track.EndEdit(),"disable is an undoable edit");
    const auto mutedText=Encode(track.data);Check(Decode(mutedText,catalog,restored,error)&&restored.muted.count(color.id)&&Encode(restored)==mutedText,"disabled properties round trip");
    auto noMuted=mutedText;pos=noMuted.find("\"muted\":[\"skyColor\"],");noMuted.erase(pos,std::string("\"muted\":[\"skyColor\"],").size());
    Check(Decode(noMuted,catalog,restored,error)&&restored.muted.empty(),"file without muted means nothing disabled");
    bad=mutedText;pos=bad.find("\"muted\":[\"skyColor\"]");bad.replace(pos,20,"\"muted\":[\"nope\"]");Check(!Decode(bad,catalog,restored,error),"unknown disabled property rejected");
    Check(track.Undo()&&!track.data.muted.count(color.id),"undo disable");
    track.BeginEdit();track.selected={first,second};track.DeleteSelected();track.EndEdit();Check(!track.data.fields.count(exposure.id),"delete removes empty channel");Check(track.Undo()&&track.data.fields.count(exposure.id),"undo delete");
    {   // Scene object pose channels (scene-object-rigs.md): linear keys, clamped ends.
        const ChannelSpec* x=FindSpec(catalog,"obj.7.x");const ChannelSpec* yaw=FindSpec(catalog,"obj.7.yaw");const ChannelSpec* fov=FindSpec(catalog,"obj.7.fov");
        Check(x&&yaw&&fov&&x==ObjectSpec(7,Rig::X)&&x->family=="objects"&&x->groupId=="7","object channels resolve from their id");
        Check(x->editLinear&&x->clampEnds&&yaw->type==ChannelType::Angle&&fov->min==1&&fov->max==179,"pose channel ranges and defaults");
        Check(!FindSpec(catalog,"obj.7.w")&&!FindSpec(catalog,"obj.0.x"),"invalid object channels rejected");
        const Value base{{-5},{}};
        SceneKeyframeTrack pose;bool on=false;
        Check(Sample(*x,{},100,base,&on).numbers[0]==-5&&!on,"no keys: the rest pose");
        pose.BeginEdit();pose.data.armed.insert(x->id);const int a=pose.Put(*x,100,{{10},{}});pose.EndEdit();
        auto& keys=pose.data.fields[x->id];
        Check(keys.size()==1&&!keys[0].hold,"a placed pose key is linear");
        Check(Sample(*x,keys,0,base,&on).numbers[0]==10&&on&&Sample(*x,keys,500,base).numbers[0]==10,"one key is a constant");
        pose.BeginEdit();const int b=pose.Put(*x,200,{{50},{}});pose.EndEdit();
        Check(Sample(*x,keys,50,base).numbers[0]==10,"before the first key: the first key");
        Check(std::fabs(Sample(*x,keys,150,base).numbers[0]-30)<1e-9,"a second key blends from the first");
        Check(Sample(*x,keys,200,base).numbers[0]==50&&Sample(*x,keys,900,base).numbers[0]==50,"lands on the next key and stays after the last");
        pose.Find(x->id,a)->hold=true;
        Check(Sample(*x,keys,150,base).numbers[0]==10&&Sample(*x,keys,199.9,base).numbers[0]==10,"a held key stays until the next");
        // Moving the object at either end of a held segment makes both of its segments linear.
        const int c=pose.Put(*x,300,{{70},{}});pose.Find(x->id,b)->hold=true;
        Check(pose.Put(*x,200,{{60},{}})==b&&!pose.Find(x->id,a)->hold&&!pose.Find(x->id,b)->hold&&!pose.Find(x->id,c)->hold,"re-posing a key clears the holds on both of its segments");
        Check(std::fabs(Sample(*x,keys,150,base).numbers[0]-35)<1e-9&&std::fabs(Sample(*x,keys,250,base).numbers[0]-65)<1e-9,"both segments blend");
        pose.Find(x->id,a)->right={true,1.0/3,0};pose.Find(x->id,b)->left={true,1.0/3,0};
        const double eased=Sample(*x,keys,125,base).numbers[0];
        Check(eased>10&&eased<22.5,"an eased segment starts slow");
        Check(pose.Put(*x,100,{{12},{}})==a&&pose.Find(x->id,a)->right.active,"re-keying a tick keeps its ease");
        pose.Find(x->id,c)->hold=true;const int d=pose.Put(*x,400,{{90},{}});
        Check(!pose.Find(x->id,c)->hold&&!pose.Find(x->id,d)->hold,"a new key after a held one makes the segment into it linear");
        // Ordinary scene keys keep their baseline outside the span, and a write keeps their holds.
        SceneKeyframeTrack env;env.Put(exposure,100,{{1},{}});env.Put(exposure,200,{{2},{}});
        Check(!env.data.fields[exposure.id][0].hold&&Sample(exposure,env.data.fields[exposure.id],300,{{3},{}}).numbers[0]==3,"scene keys unchanged");
        env.data.fields[exposure.id][0].hold=true;env.Put(exposure,200,{{2.5},{}});
        Check(env.data.fields[exposure.id][0].hold&&Sample(exposure,env.data.fields[exposure.id],150,{{3},{}}).numbers[0]==1,"a scene key can hold too");
        // Angles blend the short way, and hold when asked.
        pose.Put(*yaw,100,{{170},{}});pose.Put(*yaw,200,{{-170},{}});
        Check(std::fabs(std::fabs(Sample(*yaw,pose.data.fields[yaw->id],150,{{0},{}}).numbers[0])-180)<1e-9,"angle blends the short way");
        pose.data.fields[yaw->id][0].hold=true;
        Check(Sample(*yaw,pose.data.fields[yaw->id],150,{{0},{}}).numbers[0]==170,"angle holds");
        // File: hold flags and the attach map round trip; an attach change is one undo step.
        Rig::Attachment att;att.parent=Rig::ParentKind::Player;att.steamId=76561198000000123ull;att.playerName="ropz";att.mount="head";att.offset.pos={20,0,4};
        pose.BeginEdit();pose.data.attach[7]=att;Check(pose.EndEdit(),"attaching is an undoable edit");
        const auto text=Encode(pose.data);TrackData restoredPose;std::string poseError;
        Check(Decode(text,catalog,restoredPose,poseError)&&Encode(restoredPose)==text&&restoredPose.attach.at(7)==att,"pose keys, holds and attachments round trip");
        Check(restoredPose.fields[yaw->id][0].hold&&!restoredPose.fields[yaw->id][1].hold,"hold flags kept per key");
        Check(pose.Undo()&&pose.data.attach.empty(),"undo detaches");
        // A project whose objects are gone still loads; a malformed attach map does not.
        auto badAttach=text;const auto at=badAttach.find("\"parent\":\"player\"");badAttach.replace(at,17,"\"parent\":\"nobody\"");
        TrackData keep=restoredPose;Check(!Decode(badAttach,catalog,keep,poseError)&&Encode(keep)==text,"bad attachment rejects the file transactionally");
        auto badHold=text;const auto h=badHold.find("\"hold\":true");badHold.replace(h,11,"\"hold\":1");Check(!Decode(badHold,catalog,keep,poseError),"non-bool hold rejected");
    }
    {   // The in-world overlay's path: X/Y/Z sampled over the union of their key ticks.
        SceneKeyframeTrack path;const double rest[3]={1,2,3};
        Check(SamplePositionPath(path.data,9,rest,2,4096).empty(),"no keys: no path");
        const ChannelSpec* px=ObjectSpec(9,Rig::X);const ChannelSpec* py=ObjectSpec(9,Rig::Y);
        path.Put(*px,100,{{0},{}});path.Put(*px,200,{{100},{}});path.Put(*py,150,{{50},{}});
        auto pts=SamplePositionPath(path.data,9,rest,2,4096);
        Check(pts.size()==9,"a key, two inner points and the point before the next key per segment");
        Check(pts.front()[0]==0&&pts.front()[1]==50&&pts.front()[2]==3,"the first point: first keys, clamped ends, rest for the unkeyed");
        Check(pts.back()[0]==100&&pts.back()[1]==50&&pts.back()[2]==3,"the last point: the last keys");
        Check(pts[1][0]>0&&pts[1][0]<50,"inner points follow the curve");
        std::vector<std::array<double,3>> keyPts;SamplePositionPath(path.data,9,rest,2,4096,&keyPts);
        Check(keyPts.size()==3&&keyPts[0][0]==0&&keyPts[2][0]==100&&keyPts[1][1]==50&&keyPts[1][0]>0&&keyPts[1][0]<100,
            "a key dot on each key tick of any channel, where the path is then");
        path.data.fields[px->id][0].hold=true;
        pts=SamplePositionPath(path.data,9,rest,2,4096);
        Check(pts[4][0]==0&&pts[7][0]==0&&pts[8][0]==100,"a held segment stays put until just before the next key");
        Check(SamplePositionPath(path.data,9,rest,50,5).size()==5,"a tight budget keeps the keys and the steps");
        path.data.muted.insert(px->id);
        pts=SamplePositionPath(path.data,9,rest,2,4096);
        Check(pts.size()==1&&pts[0][0]==1&&pts[0][1]==50,"a muted channel sits at rest and adds no ticks");
    }
    std::cout<<"Scene key catalog, sampling, transactions and serialization passed.\n";return 0;
} catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
